exploreUrl:
@js:
    java.toast("正在努力加载中，请稍后");
var sort = [];
var push = (title, url, type1, type2) => {
    sort.push({
        title: title,
        url: url,
        style: {
            layout_flexGrow: type1,
            layout_flexBasisPercent: type2
        }
    });
};
var sites = [{
        u: "http://m.badaoge.org/list.html",
        ti: "༺ˇ»`全部分类´«ˇ༻",
        reb: /\/(.*)\/(.*)\/(\d+)\.html/,
        rea: "/$1/$2/{{page}}.html"
    },
    {
        u: "http://m.badaoge.org/top.html",
        ti: "༺ˇ»`全部排行´«ˇ༻",
        reb: /\/(.*)-(.*)-(\d+)\//,
        rea: "/$1-$2-{{page}}/"
    }];
for (var site of sites) {
    var o = org.jsoup.Jsoup.parse(java.ajax(site.u));
    var s = o.select('div.content a');
    push(site.ti, "", "1", "1");
    for (var i = 0; i < s.size(); i++) {
        var urls = String(s[i].attr("href")).replace(site.reb,site.rea);
        if (i + 1 <= s.length - s.length % 3) {
            push(s[i].text(), urls, "1", "0.25")
        } else {
        push(s[i].text(), urls, "-1", "0.29")
        }
    }
}
push("༺ˇ»`全本小说´«ˇ༻", `/wanben/1_{{page}}/`, "1", "1")
JSON.stringify(sort);

ruleBookInfo.init:
@js:
X = (x) => java.getString(x);
({
    n: X("[property$=book_name]@content"),
    a: X("[property$=author]@content"),
    k: X("[property~=category|status|update_time]@content\#\#T\#\#&nbsp;&nbsp;"),
    l: X("[property~=las?test_chapter_name]@content"),
    i: X("[property$=description]@content\#\#简介[：:]"),
    c: X("[property$=image]@content")
});

ruleExplore.coverUrl:
a@href
<js>
var id = result.match(/(\d+)/)[1];
var iid = parseInt(id/1000);
'http://m.badaoge.org/files/article/image/'+iid+'/'+id+'/'+id+'s.jpg';
</js>

